   * @param {module:ol/events/Event} event Image change event.
   * @private
   */
  handleImageChange_(event) {
    const image = /** @type {module:ol/Image} */ (event.target);
    if (image.getState() === ImageState.LOADED) {
      this.renderIfReadyAndVisible();
    }
